input.content:
:root {
  --bg-1: #0d1422;
  --bg-2: #121d31;
  --panel: rgba(12, 18, 32, 0.75);
  --panel-border: rgba(148, 179, 255, 0.3);
  --accent: #7ae0ff;
  --accent-2: #ffdd7d;
  --danger: #ff6b6b;
  --good: #92f0a9;
  --text: #ebf4ff;
  --muted: #b3c9e8;
  --shadow: rgba(0, 0, 0, 0.4);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  min-height: 100%;
  background: radial-gradient(circle at top, #1a2c45, var(--bg-1) 38%, #090d18 100%);
  color: var(--text);
  font-family: Inter, "Segoe UI", sans-serif;
}

body {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: env(safe-area-inset-top, 12px) env(safe-area-inset-right, 12px) env(safe-area-inset-bottom, 12px) env(safe-area-inset-left, 12px);
}

.game-shell {
  position: relative;
  width: min(96vw, 980px);
  min-height: min(92vh, 760px);
  border-radius: 20px;
  overflow: hidden;
  background: rgba(12, 17, 28, 0.9);
  border: 1px solid var(--panel-border);
  box-shadow: 0 20px 60px var(--shadow);
}

.hud {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 10;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
  padding: 18px 22px 0;
  pointer-events: none;
}

.brand-block {
  padding: 10px 12px 8px;
  border-radius: 12px;
  background: rgba(11, 18, 29, 0.45);
  backdrop-filter: blur(6px);
  border: 1px solid rgba(120, 148, 214, 0.2);
}

.eyebrow {
  font-size: 0.7rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--accent);
  opacity: 0.9;
}

h1 {
  margin: 6px 0 0;
  font-size: clamp(1.2rem, 2vw, 2.2rem);
  letter-spacing: 0.04em;
}

.stats {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.stat-box {
  min-width: 100px;
  padding: 10px 14px;
  border-radius: 12px;
  background: rgba(15, 26, 40, 0.7);
  border: 1px solid rgba(143, 177, 255, 0.2);
  text-align: center;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.05);
}

.stat-box span {
  display: block;
  font-size: 0.72rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}

.stat-box strong {
  display: block;
  margin-top: 4px;
  font-size: 1.4rem;
  font-weight: 700;
}

#gameCanvas {
  display: block;
  width: 100%;
  height: 100%;
  min-height: 600px;
  background: linear-gradient(#9ad4ff 0%, #dbedff 30%, #7bcf7d 30%, #0d2c26 100%);
}

.message-bar {
  position: absolute;
  left: 50%;
  bottom: 18px;
  transform: translateX(-50%);
  width: min(78%, 640px);
  padding: 12px 18px;
  text-align: center;
  font-size: 0.96rem;
  line-height: 1.4;
  border-radius: 999px;
  background: rgba(7, 12, 20, 0.72);
  border: 1px solid rgba(147, 188, 255, 0.2);
  box-shadow: 0 8px 20px rgba(0,0,0,0.25);
  z-index: 8;
}

.overlay {
  position: absolute;
  inset: 0;
  display: none;
  place-items: center;
  background: rgba(6, 10, 18, 0.5);
  backdrop-filter: blur(2px);
  z-index: 20;
}

.overlay.visible {
  display: grid;
}

.panel {
  width: min(82%, 420px);
  padding: 28px 26px 22px;
  border-radius: 18px;
  background: rgba(10, 18, 32, 0.86);
  border: 1px solid rgba(138, 170, 255, 0.28);
  box-shadow: 0 18px 40px rgba(6,5,15,0.38);
  text-align: center;
}

.small-tag {
  margin: 0;
  color: var(--accent);
  letter-spacing: 0.18em;
  font-size: 0.68rem;
  text-transform: uppercase;
}

.panel h2 {
  margin: 10px 0 12px;
  font-size: clamp(2rem, 4vw, 2.7rem);
}

.panel p {
  margin: 0 0 18px;
  line-height: 1.5;
  color: var(--muted);
}

button {
  appearance: none;
  border: none;
  border-radius: 12px;
  background: linear-gradient(180deg, #89e5ff, #50b1ff);
  color: #072037;
  font-weight: 800;
  letter-spacing: 0.04em;
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
  box-shadow: 0 10px 20px rgba(95, 171, 255, 0.3);
}

button:hover { transform: translateY(-1px); }

button:active { transform: translateY(1px); }

#startButton {
  width: min(100%, 220px);
  padding: 14px 18px;
  font-size: 1rem;
}

.touch-controls {
  position: absolute;
  left: 18px;
  bottom: 18px;
  z-index: 12;
  display: none;
  flex-direction: column;
  gap: 10px;
  pointer-events: auto;
}

.middle-row {
  display: flex;
  gap: 10px;
}

.move-btn {
  width: 52px;
  height: 52px;
  padding: 0;
  font-size: 1.3rem;
  background: rgba(20, 35, 52, 0.8);
  color: var(--text);
  border: 1px solid rgba(143, 177, 255, 0.18);
  box-shadow: none;
}

@media (max-width: 640px) {
  .game-shell {
    width: 100vw;
    min-height: 100vh;
    border-radius: 0;
  }

  .hud {
    padding: 14px 12px 0;
    gap: 8px;
  }

  .brand-block {
    padding: 8px 10px 6px;
  }

  .stat-box {
    min-width: 70px;
    padding: 8px 8px;
  }

  .stat-box strong {
    font-size: 1.1rem;
  }

  .message-bar {
    width: calc(100% - 26px);
    bottom: 115px;
    font-size: 0.82rem;
  }

  .touch-controls {
    display: flex;
  }

  #gameCanvas {
    min-height: 100vh;
  }
}

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const overlay = document.getElementById('overlay');
const overlayTitle = document.getElementById('overlayTitle');
const overlayText = document.getElementById('overlayText');
const startButton = document.getElementById('startButton');
const messageBox = document.getElementById('messageBox');
const healthLabel = document.getElementById('healthLabel');
const timerLabel = document.getElementById('timerLabel');
const beaconLabel = document.getElementById('beaconLabel');

const world = {
  width: 1600,
  height: 900,
  groundY: 550,
  station: { x: 1460, y: 430, w: 120, h: 120 },
};

const input = {
  up: false,
  down: false,
  left: false,
  right: false,
};

const time = {
  last: 0,
  elapsed: 0,
  timer: 90,
  gameOver: false,
  won: false,
  phase: 'intro',
  giantPauseTimer: 0,
};

const player = {
  x: 120,
  y: world.groundY - 24,
  radius: 18,
  speed: 140,
  health: 3,
  beacons: 0,
  invulnerable: 0,
};

const giantess = {
  x: 700,
  y: 110,
  width: 460,
  height: 520,
  feetY: 450,
  speed: 85,
  targetX: 700,
  direction: 1,
  stuck: 0,
  nearPlayer: false,
  stepTime: 0,
  pauseTimer: 0,
  phase: 'patrol',
  footFlash: 0,
};

const beacons = [
  { x: 320, y: 200, collected: false },
  { x: 700, y: 240, collected: false },
  { x: 1180, y: 195, collected: false },
];

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function setMessage(text) {
  messageBox.textContent = text;
}

function startGame() {
  overlay.classList.remove('visible');
  time.phase = 'playing';
  time.timer = 90;
  time.gameOver = false;
  time.won = false;
  time.elapsed = 0;
  player.x = 120;
  player.y = world.groundY - 24;
  player.health = 3;
  player.beacons = 0;
  player.invulnerable = 0;
  giantess.x = 700;
  giantess.targetX = 700;
  giantess.direction = 1;
  giantess.phase = 'patrol';
  giantess.pauseTimer = 0;
  giantess.footFlash = 0;
  giantess.nearPlayer = false;
  beacons.forEach((b) => { b.collected = false; });
  updateHud();
  setMessage('Collect three rooftop beacons and reach the station exit while the giantess patrols the streets.');
}

function updateHud() {
  healthLabel.textContent = String(player.health);
  timerLabel.textContent = String(Math.max(0, Math.ceil(time.timer)));
  beaconLabel.textContent = `${player.beacons} / ${beacons.length}`;
}

function setOverlay(title, text, buttonText = 'Play Again') {
  overlayTitle.textContent = title;
  overlayText.textContent = text;
  startButton.textContent = buttonText;
  overlay.classList.add('visible');
}

function endGame(win = false) {
  time.gameOver = true;
  time.won = win;
  if (win) {
    setOverlay('You Escaped!', 'The station platform is yours. The giantess is left behind in the city lights.', 'Play Again');
    setMessage('Victory! You reached the station with all beacons secured.');
  } else {
    setOverlay('Caught!', 'The giantess closed in before you could escape. Try the route again from the alley.', 'Retry');
    setMessage('You were stepped on before reaching the station.');
  }
}

function resetTouchButtons() {
  Object.keys(input).forEach((key) => { input[key] = false; });
}

function handleKeyState(code, isDown) {
  const mapping = {
    ArrowUp: 'up',
    KeyW: 'up',
    ArrowDown: 'down',
    KeyS: 'down',
    ArrowLeft: 'left',
    KeyA: 'left',
    ArrowRight: 'right',
    KeyD: 'right',
  };
  const key = mapping[code];
  if (key) input[key] = isDown;
}

window.addEventListener('keydown', (event) => {
  handleKeyState(event.code, true);
  if (event.code === 'Space' && time.phase !== 'playing') {
    startGame();
  }
});

window.addEventListener('keyup', (event) => {
  handleKeyState(event.code, false);
});

startButton.addEventListener('click', () => {
  startGame();
});

const touchButtons = document.querySelectorAll('.move-btn');
touchButtons.forEach((button) => {
  const key = button.dataset.key;
  const press = (down) => {
    input[key] = down;
    button.style.opacity = down ? '1' : '0.8';
  };
  button.addEventListener('pointerdown', () => press(true));
  button.addEventListener('pointerup', () => press(false));
  button.addEventListener('pointerleave', () => press(false));
  button.addEventListener('pointercancel', () => press(false));
});

function updatePlayer(dt) {
  let dx = 0;
  let dy = 0;

  if (input.left) dx -= 1;
  if (input.right) dx += 1;
  if (input.up) dy -= 1;
  if (input.down) dy += 1;

  if (dx || dy) {
    const length = Math.hypot(dx, dy) || 1;
    dx /= length;
    dy /= length;
    const nextX = player.x + dx * player.speed * dt;
    const nextY = player.y + dy * player.speed * dt;
    player.x = clamp(nextX, 50, world.width - 50);
    player.y = clamp(nextY, 70, world.groundY);
  }

  if (player.invulnerable > 0) {
    player.invulnerable -= dt;
  }
}

function updateGiantess(dt) {
  const playerNear = Math.abs(player.x - giantess.x) < 260;
  giantess.nearPlayer = playerNear;

  if (giantess.phase === 'patrol') {
    giantess.x += giantess.direction * giantess.speed * dt;
    if (giantess.x < 330 || giantess.x > 1180) {
      giantess.direction *= -1;
      giantess.x = clamp(giantess.x, 330, 1180);
    }

    if (Math.random() < 0.009) {
      giantess.phase = 'pause';
      giantess.pauseTimer = 1.9 + Math.random() * 1.8;
      giantess.footFlash = 0.6;
      setMessage('The giantess slows to a stop, giving you a brief window to move.');
    }
  }

  if (giantess.phase === 'pause') {
    giantess.pauseTimer -= dt;
    giantess.footFlash = Math.max(0, giantess.footFlash - dt * 1.3);
    if (giantess.pauseTimer <= 0) {
      giantess.phase = 'patrol';
      giantess.direction *= -1;
      setMessage('The giantess resumes her walk through the city block.');
    }
  }

  giantess.stepTime += dt;
  if (giantess.stepTime > 0.7) {
    giantess.stepTime = 0;
  }
}

function collectBeacons() {
  beacons.forEach((beacon) => {
    if (beacon.collected) return;
    const dx = player.x - beacon.x;
    const dy = player.y - beacon.y;
    if (Math.hypot(dx, dy) < 28) {
      beacon.collected = true;
      player.beacons += 1;
      updateHud();
      setMessage('Beacon secured. The station exit is closer now.');
    }
  });
}

function checkPlayerDamage() {
  const distanceX = Math.abs(player.x - giantess.x);
  const distanceY = Math.abs(player.y - 280);
  const danger = distanceX < 110 && distanceY < 150;

  if (danger && player.invulnerable <= 0) {
    player.health -= 1;
    player.invulnerable = 1.5;
    updateHud();
    setMessage('The giantess stomped near you! Keep moving.');
  }

  if (player.health <= 0) {
    endGame(false);
  }
}

function checkStationExit() {
  const nearExit = player.x > world.station.x - 20 && player.y > world.station.y;
  if (nearExit && player.beacons >= beacons.length) {
    endGame(true);
  }
}

function update(dt) {
  if (time.phase !== 'playing' || time.gameOver) return;

  time.elapsed += dt;
  time.timer -= dt;
  if (time.timer <= 0) {
    endGame(false);
  }

  updatePlayer(dt);
  updateGiantess(dt);
  collectBeacons();
  checkPlayerDamage();
  checkStationExit();
  updateHud();
}

function drawBackground() {
  const sky = ctx.createLinearGradient(0, 0, 0, canvas.height);
  sky.addColorStop(0, '#9ed9ff');
  sky.addColorStop(0.34, '#dfefff');
  sky.addColorStop(0.35, '#7ed290');
  sky.addColorStop(1, '#193b2d');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = 'rgba(18, 24, 36, 0.76)';
  ctx.fillRect(0, 380, canvas.width, 220);

  for (let i = 0; i < 7; i++) {
    const x = 60 + i * 210;
    ctx.fillStyle = 'rgba(20, 36, 48, 0.85)';
    ctx.fillRect(x, 200, 140, 180);
    ctx.fillStyle = 'rgba(80, 112, 130, 0.7)';
    for (let row = 0; row < 4; row++) {
      for (let col = 0; col < 2; col++) {
        ctx.fillRect(x + 14 + col * 52, 220 + row * 34, 24, 18);
      }
    }
  }

  ctx.fillStyle = '#264b52';
  ctx.fillRect(0, world.groundY, canvas.width, 400);

  ctx.fillStyle = '#3a4a60';
  ctx.fillRect(1100, 240, 24, 130);
  ctx.fillRect(1330, 204, 20, 180);

  ctx.fillStyle = '#d9b26a';
  ctx.fillRect(world.station.x, world.station.y, world.station.w, world.station.h);
  ctx.fillStyle = '#f1d78a';
  ctx.fillRect(world.station.x + 20, world.station.y + 16, 76, 54);
  ctx.fillRect(world.station.x + 34, world.station.y + 90, 50, 20);
}

function drawBeacons() {
  beacons.forEach((beacon) => {
    if (beacon.collected) return;
    const pulse = 0.5 + Math.sin(performance.now() * 0.006 + beacon.x) * 0.35;
    ctx.save();
    ctx.translate(beacon.x, beacon.y);
    ctx.fillStyle = `rgba(255, 216, 108, ${0.8 + pulse * 0.2})`;
    ctx.beginPath();
    ctx.arc(0, 0, 10 + pulse * 4, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,0.8)';
    ctx.beginPath();
    ctx.arc(0, 0, 3, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  });
}

function drawPlayer() {
  ctx.save();
  ctx.translate(player.x, player.y);
  if (player.invulnerable > 0 && Math.floor(player.invulnerable * 10) % 2 === 0) {
    ctx.globalAlpha = 0.35;
  }
  ctx.fillStyle = '#f6d0a8';
  ctx.beginPath();
  ctx.arc(0, 0, player.radius, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = '#1d2231';
  ctx.fillRect(-6, 0, 12, 22);
  ctx.fillStyle = '#8ed0ff';
  ctx.fillRect(-9, 7, 18, 8);
  ctx.fillStyle = '#f9f0de';
  ctx.fillRect(-9, 20, 5, 10);
  ctx.fillRect(4, 20, 5, 10);
  ctx.restore();
}

function drawGiantess() {
  const bodyX = giantess.x;
  const bodyY = giantess.y + 200;

  ctx.save();
  ctx.translate(bodyX, bodyY);

  ctx.fillStyle = '#f8d4b5';
  ctx.fillRect(-160, -54, 300, 220);

  ctx.fillStyle = '#e9c49a';
  ctx.fillRect(-110, -220, 220, 170);
  ctx.fillStyle = '#f0d6bf';
  ctx.fillRect(-95, -200, 190, 120);

  ctx.fillStyle = 'rgba(39, 28, 17, 0.82)';
  ctx.fillRect(-70, -12, 140, 90);

  ctx.fillStyle = '#f8d4b5';
  ctx.fillRect(-110, 150, 94, 210);
  ctx.fillRect(16, 150, 94, 210);

  ctx.fillStyle = '#f5d7b9';
  ctx.fillRect(-80, 350, 52, 54);
  ctx.fillRect(28, 350, 52, 54);
  ctx.fillStyle = '#f4bf8d';
  ctx.fillRect(-148, 330, 40, 95);
  ctx.fillRect(108, 330, 40, 95);

  ctx.fillStyle = 'rgba(255, 255, 255, 0.14)';
  if (giantess.phase === 'pause') {
    ctx.fillStyle = 'rgba(255,255,255,0.24)';
  }
  ctx.fillRect(-150, 170, 300, 110);

  ctx.restore();

  ctx.fillStyle = '#f0d9bf';
  const stride = giantess.phase === 'pause' ? 0 : Math.sin(performance.now() * 0.005) * 8;
  ctx.fillRect(giantess.x - 130, 440 + stride, 70, 18);
  ctx.fillRect(giantess.x + 46, 440 - stride, 70, 18);
  ctx.fillStyle = '#d6a67d';
  ctx.fillRect(giantess.x - 160, 454, 70, 16);
  ctx.fillRect(giantess.x + 90, 454, 70, 16);
}

function drawMiniMapHint() {
  const stationX = world.station.x / world.width * 130;
  const playerX = player.x / world.width * 130;
  const giantX = giantess.x / world.width * 130;

  ctx.fillStyle = 'rgba(10, 16, 28, 0.7)';
  ctx.fillRect(canvas.width - 150, 18, 132, 36);

  ctx.fillStyle = '#85ddff';
  ctx.fillRect(canvas.width - 140 + stationX * 0.86, 28, 10, 14);
  ctx.fillStyle = '#f8d977';
  ctx.fillRect(canvas.width - 140 + playerX * 0.86, 28, 8, 14);
  ctx.fillStyle = '#ff8c82';
  ctx.fillRect(canvas.width - 140 + giantX * 0.86, 28, 10, 14);
}

function draw() {
  drawBackground();
  drawMiniMapHint();
  drawBeacons();
  drawPlayer();
  drawGiantess();

  ctx.fillStyle = '#ffffff';
  ctx.font = 'bold 16px Segoe UI';
  ctx.fillText('Station', world.station.x + 16, world.station.y - 14);

  if (time.phase !== 'playing') {
    ctx.fillStyle = 'rgba(0, 0, 0, 0.18)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }
}

let lastTime = 0;
function gameLoop(timestamp) {
  const dt = Math.min(0.033, (timestamp - lastTime) / 1000 || 0.016);
  lastTime = timestamp;

  update(dt);
  draw();
  requestAnimationFrame(gameLoop);
}

setOverlay('Start the Run', 'Explore the city as a tiny pedestrian. The giantess walks the streets in slow loops, pauses for a close-up, and stomps anything in reach.', 'Begin');
updateHud();
requestAnimationFrame(gameLoop);

