const skin = '#f1b58f';
const litSkin = '#ffd2ae';
const shadowSkin = '#ce876d';
ctx.lineWidth = 10;
ctx.lineJoin = 'round';

// Arms emerge from the shoulders and hang beside the hips.
ctx.strokeStyle = shadowSkin;
ctx.lineWidth = 38;
ctx.beginPath();
ctx.moveTo(-145, -38);
ctx.quadraticCurveTo(-190, 56, -178, 176);
ctx.moveTo(132, -38);
ctx.quadraticCurveTo(180, 60, 168, 176);
ctx.stroke();
ctx.strokeStyle = skin;
ctx.lineWidth = 27;
ctx.beginPath();
ctx.moveTo(-145, -42);
ctx.quadraticCurveTo(-177, 52, -166, 162);
ctx.moveTo(132, -42);
ctx.quadraticCurveTo(166, 52, 156, 162);
ctx.stroke();

// Broad coat-dress silhouette, tapered at the waist.
ctx.fillStyle = '#a54668';
ctx.beginPath();
ctx.moveTo(-100, -78);
ctx.quadraticCurveTo(-152, -10, -145, 75);
ctx.lineTo(-125, 155);
ctx.quadraticCurveTo(0, 194, 125, 155);
ctx.lineTo(145, 75);
ctx.quadraticCurveTo(152, -10, 100, -78);
ctx.closePath();
ctx.fill();
ctx.fillStyle = '#d2687c';
ctx.beginPath();
ctx.moveTo(-18, -70);
ctx.lineTo(0, 160);
ctx.lineTo(42, 166);
ctx.lineTo(27, -72);
ctx.closePath();
ctx.fill();
ctx.fillStyle = '#f3d09a';
ctx.fillRect(-9, -35, 18, 12);
ctx.fillRect(-9, 20, 18, 12);
ctx.fillRect(-9, 76, 18, 12);

// Neck and face, with long hair framing the head.
ctx.fillStyle = shadowSkin;
ctx.fillRect(-32, -117, 64, 53);
ctx.fillStyle = skin;
ctx.fillRect(-25, -118, 50, 46);
ctx.fillStyle = '#39263b';
ctx.beginPath();
ctx.moveTo(-82, -235);
ctx.quadraticCurveTo(-100, -305, -54, -333);
ctx.quadraticCurveTo(0, -367, 57, -328);
ctx.quadraticCurveTo(98, -292, 75, -209);
ctx.lineTo(49, -165);
ctx.lineTo(-55, -165);
ctx.closePath();
ctx.fill();
ctx.fillStyle = litSkin;
ctx.beginPath();
ctx.ellipse(0, -267, 55, 74, 0, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = '#39263b';
ctx.beginPath();
ctx.moveTo(-58, -289);
ctx.quadraticCurveTo(-8, -327, 56, -295);
ctx.lineTo(44, -273);
ctx.quadraticCurveTo(0, -293, -52, -263);
ctx.closePath();
ctx.fill();
ctx.fillStyle = '#4d3448';
ctx.fillRect(-80, -279, 21, 100);
ctx.fillRect(58, -285, 22, 107);
ctx.fillStyle = '#45303a';
ctx.fillRect(-28, -256, 8, 7);
ctx.fillRect(18, -256, 8, 7);
ctx.strokeStyle = '#a7565c';
ctx.lineWidth = 3;
ctx.beginPath();
ctx.moveTo(-10, -220);
ctx.quadraticCurveTo(0, -213, 11, -220);
ctx.stroke();
ctx.fillStyle = '#f4e3d0';
ctx.fillRect(-62, -198, 124, 9);

// Long legs and tiny flats place her feet on the distant street plane.
const stride = giantess.phase === 'pause' ? 0 : Math.sin(performance.now() * 0.005) * 9;
ctx.fillStyle = shadowSkin;
ctx.fillRect(-83, 145, 61, 210 + stride);
ctx.fillRect(22, 145, 61, 210 - stride);
ctx.fillStyle = skin;
ctx.fillRect(-76, 150, 48, 202 + stride);
ctx.fillRect(29, 150, 48, 202 - stride);
ctx.fillStyle = '#ead3bc';
ctx.beginPath();
ctx.ellipse(-46, 360 + stride, 42, 15, 0, 0, Math.PI * 2);
ctx.ellipse(59, 360 - stride, 42, 15, 0, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = '#c49a82';
ctx.fillRect(-77, 365 + stride, 60, 7);
ctx.fillRect(28, 365 - stride, 60, 7);

if (giantess.phase === 'pause') {
  ctx.fillStyle = 'rgba(255,255,255,0.13)';
  ctx.fillRect(-145, -340, 290, 700);
}

